use vstd::prelude::*;

verus! {

fn replace(arr: &Vec<i32>, k: i32) -> (out: Vec<i32>)
    ensures
        out.len() == arr.len(),
        forall|i: int|
            0 <= i < arr.len() ==> (
                if arr[i] > k {
                    out[i] == -1
                } else {
                    out[i] == arr[i]
                }
            ),
{
    let mut out: Vec<i32> = Vec::new();
    let mut idx: usize = 0;

    while idx < arr.len()
        invariant
            out.len() == idx,
            idx <= arr.len(),
            forall|i: int|
                0 <= i < idx ==> (
                    if arr[i] > k {
                        out[i] == -1
                    } else {
                        out[i] == arr[i]
                    }
                ),
    {
        let v = arr[idx];
        if v > k {
            out.push(-1);
        } else {
            out.push(v);
        }
        idx += 1;
    }

    out
}

} // verus!